---2倍速播放速度控件（num1=是否可操作，1可操作2不可操作，0为默认上次选择：num2=是否默认开启1开启2不开启，0为默认上次选择）
---播放大招控件（num1=是否可操作，1可操作2不可操作，0为默认上次选择：num2=是否默认开启1开启2不开启，0为默认上次选择）
---自动战斗控件（num1=是否可操作，1可操作2不可操作，0为默认上次选择：num2=是否默认开启1开启2不开启，0为默认上次选择）
function UIBattleSettingMgr:InitQuestPlayerPrefs()
    local isGuideQuest = GamePlayGuideMgr and GamePlayGuideMgr.dataPlay and #GamePlayGuideMgr.dataPlay > 0
    local isPVPMode = BattleInfo and BattleInfo.gameMode == Constants.GameMode.PVP
    
    if isGuideQuest then
        self:SetBtnAutoInteractive(false)
        self:SetBtnDoubleInteractive(false)
        self:SetAutoBattleState(false, false)
        self:SetDoubleRateState(1, false)
    --elseif isPVPMode then
    --    self:SetBtnAutoInteractive(false)
    --    self:SetBtnDoubleInteractive(false)
    --    self:SetBtnSkipInteractive(false)
    --    self:SetAutoBattleState(false)
    --    self:SetDoubleRateState(true)
    --    self:SetSkillSkipState(true)
    else
        self:HandleBattleInfoSetting()
    end

    if self.manualEnd > 0 then
        local isClose = not (self.manualEnd > 1)
        self.canManualEnd = isClose
    else
        --- 手动跳过回合
        PlayerPrefsUtility.SetEncryptedInt(self.playerUID..Constants.PlayerPrefsType.BattlePassRoundByClick, 0)  -- 默认关闭
        local passRoundState = PlayerPrefsUtility.GetEncryptedInt(self.playerUID .. Constants.PlayerPrefsType.BattlePassRoundByClick, 0)
        self.canManualEnd = passRoundState == 1
    end
end

function UIBattleSettingMgr:HandleBattleInfoSetting()
    local unlockState = self:CheckUnLockStateOfPlayerSetting()
    local isReplay = self.uiBattleMgr.playMode == Constants.UIPlayMode.Replay
    if isReplay then
        self:SetBtnAutoInteractive(false)
        self:SetAutoBattleState(true, false)
        ---两倍速
        local playerDojo = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent).playerDojo
        local vo = CfUtils.GetCfVo(AutoIds.IdSetting4032, "WelfareSettingVo", 1)
        local isHavePrivilegeCard = playerDojo:IsHavePrivilegeCardById(tonumber(vo.giftId))
        local lastSpeed = PlayerPrefsUtility.GetEncryptedInt(self.playerUID .. Constants.PlayerPrefsType.BattleDoubleRateState, 0)
        if self.speedDefault == 0 then
            if lastSpeed == 3 and not isHavePrivilegeCard then
                if unlockState then
                    lastSpeed = 2
                else
                    lastSpeed = 1
                end
            end

            if lastSpeed == 2 and not unlockState then
                lastSpeed = 1
            end
            self:SetDoubleRateState(lastSpeed, false)
        else
            self:SetDoubleRateState(unlockState and self.speedDefault or 1, false)
        end
        --local isDouble = (self.speedDefault == 0)
        --        and (PlayerPrefsUtility.GetEncryptedInt(self.playerUID .. Constants.PlayerPrefsType.BattleDoubleRateState, 0) == 1 and unlockState)
        --        --or self.speedDefault == 1
        --self:SetDoubleRateState(isDouble)
    else
        self:SetBtnAutoInteractive(self.automaticInteractive ~= 2)
        self:SetBtnDoubleInteractive(self.speedInteractive ~= 2)
        ---两倍速
        local playerDojo = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent).playerDojo
        local vo = CfUtils.GetCfVo(AutoIds.IdSetting4032, "WelfareSettingVo", 1)
        local isHavePrivilegeCard = playerDojo:IsHavePrivilegeCardById(tonumber(vo.giftId))
        local lastSpeed = PlayerPrefsUtility.GetEncryptedInt(self.playerUID .. Constants.PlayerPrefsType.BattleDoubleRateState, 0)
        if self.speedDefault == 0 then
            if lastSpeed == 3 and not isHavePrivilegeCard then
                if unlockState then
                    lastSpeed = 2
                else
                    lastSpeed = 1
                end
            end
            
            if lastSpeed == 2 and not unlockState then
                lastSpeed = 1
            end
            self:SetDoubleRateState(lastSpeed, false)
        else
            self:SetDoubleRateState(unlockState and self.speedDefault or 1, false)
        end
        ---自动战斗
        local isAuto = (self.automaticDefault == 0)
                and (PlayerPrefsUtility.GetEncryptedInt(self.playerUID .. Constants.PlayerPrefsType.BattleAutoState, 0) == 1 and unlockState)
                or self.automaticDefault == 1
        self:SetAutoBattleState(isAuto, false)
    end
   
end

---CheckUnLockStateOfPlayerSetting
---获取玩家 战斗特殊设置 解锁状态
function UIBattleSettingMgr:CheckUnLockStateOfPlayerSetting()
    local questId = Constants.UNLOCK_PLAYERSETTING_QUESTID
    local strKey = self.uiBattleMgr.strKey
    local playMode = self.uiBattleMgr.playMode
    local condition_1 = (not IsNull(strKey) and strKey == Constants.KeyRandomSeed)--通过钥匙解锁玩家模式
    local condition_2 = (playMode and playMode == Constants.UIPlayMode.Replay)--战斗录像
    if condition_1 or condition_2 then
        return true
    end
    ---战斗中只需要判断服务器是否解锁就行，如未解锁不应该进入战斗，只处理这种情况
    local isPass = QuestConfMgr:GetInstance():IsPassQuest(questId)
    return isPass
end

---GetGameIsAutoBattle
---获取当前 游戏自动战斗执行 执行状态
function UIBattleSettingMgr:GetGameIsAutoBattle()
    local playerUID = self.playerUID -- 玩家 UID
    local battleAutoState = PlayerPrefsUtility.GetEncryptedInt(playerUID .. Constants.PlayerPrefsType.BattleAutoState, 0) -- 本子字段状态
    local unlockState = self:CheckUnLockStateOfPlayerSetting() -- 功能解锁状态
    self.isAutoBattle = battleAutoState == 1 and unlockState -- 自动战斗字段
    return self.isAutoBattle
end

---SetAutoBattleState
---改变自动战斗状态
---@param autoState boolean 当前自动战斗状态 
function UIBattleSettingMgr:SetAutoBattleState(autoStateNow, save)
    -- print("[设置] 自动", autoStateNow, save, debug.traceback())
    if save == true then
        PlayerPrefsUtility.SetEncryptedInt(self.playerUID .. Constants.PlayerPrefsType.BattleAutoState, autoStateNow and 1 or 0)
    end
    self.isAutoBattle = autoStateNow
end

---SetDoubleRateState
---改变两倍速状态
---@param doubleRateStateNow boolean 当前两倍速状态
function UIBattleSettingMgr:SetDoubleRateState(gameSpeed, save)
    -- print("[设置] 倍速", gameSpeed, save, debug.traceback())
    if save == true then
        PlayerPrefsUtility.SetEncryptedInt(self.playerUID .. Constants.PlayerPrefsType.BattleDoubleRateState, gameSpeed)
    end
    self.nowGameSpeed = gameSpeed
end

